{"command":"cd /testbed/migration-recon && python - <<'EOF'
import sqlite3

def tables(db):
    con = sqlite3.connect("file:%s?mode=ro" % db, uri=True)
    rows = con.execute("SELECT name, type FROM sqlite_master WHERE type IN ('table','view') ORDER BY name").fetchall()
    con.close()
    return rows

for db in ("databases/source.db", "databases/target.db"):
    print(db, "objects:", tables(db))

def count(db, t):
    con = sqlite3.connect("file:%s?mode=ro" % db, uri=True)
    n = con.execute('SELECT COUNT(*) FROM "%s"' % t).fetchone()[0]
    con.close()
    return n

for t in ("customers", "orders", "orders_archive", "order_items", "payments", "addresses"):
    for db in ("databases/source.db", "databases/target.db"):
        try:
            print("%-14s %-8s %d" % (t, db, count(db, t)))
        except sqlite3.OperationalError as e:
            print("%-14s %-8s ERR: %s" % (t, db, e))
EOF"}

